#!/usr/bin/env bash
# Generate ~/.codex/AGENTS.md from the shared, model-agnostic AI rules.
# Edit those sources, never the generated file.
set -euo pipefail

dotfiles="${DOTFILES_HOME:-$HOME/.dotfiles}"
claude_md="$dotfiles/claude/CLAUDE.md"
out="$HOME/.codex/AGENTS.md"
mkdir -p "$HOME/.codex"
tmp="$(mktemp "$out.XXXXXX")"
trap 'rm -f "$tmp"' EXIT

# The list comes from CLAUDE.md's @imports rather than a second copy here, so the
# agents cannot drift onto different sets. Only ai-rules/ imports are shared.
#
# Claude also accepts inline, relative, and nested imports, which this cannot
# read. Anything mentioning ai-rules that is not a standalone absolute import
# aborts rather than silently leaving Codex a shorter rule set than Claude has.
sources=()
while IFS= read -r src; do
  sources+=("$src")
done < <(sed -n 's|^@\(/[^[:space:]]*/ai-rules/[^[:space:]]*\)$|\1|p' "$claude_md")
[ ${#sources[@]} -gt 0 ] || { echo "no ai-rules imports found in $claude_md" >&2; exit 1; }

recognised=${#sources[@]}
mentioned=$(grep -c '@[^[:space:]]*ai-rules/' "$claude_md" || true)
[ "$mentioned" -eq "$recognised" ] || {
  echo "$claude_md has $mentioned ai-rules import(s) but only $recognised are standalone absolute paths." >&2
  echo "Rewrite the rest in that form, or teach this script to expand them." >&2
  exit 1
}

{
  printf '<!-- GENERATED by ~/.dotfiles/codex/build-agents.sh. Edit the sources, not this file. -->\n\n'
  for src in "${sources[@]}"; do
    [ -f "$src" ] || { echo "missing import: $src" >&2; exit 1; }
    grep -q '^@' "$src" && { echo "$src imports another file; this script does not expand nested imports." >&2; exit 1; }
    cat "$src"
    printf '\n\n'
  done
} > "$tmp"

mv "$tmp" "$out"
printf 'wrote %s (%s bytes) from %d shared file(s)\n' "$out" "$(wc -c < "$out" | tr -d ' ')" "$recognised"
